import { searchCharacters, getCharacterById } from './BangumiRequest.js';
import React, { useState, useRef, useEffect, useCallback } from 'react';
import debounce from 'lodash.debounce';
import styles from './styles/InputStyles.module.css';

function GuessingCharacter() {
    const [inputTerm, setInputTerm] = useState('');
    const [results, setResults] = useState([]);
    const [isLoading, setIsLoading] = useState(false);
    const [isOpen, setIsOpen] = useState(false);
    const dropdownRef = useRef(null);

    // 使用useCallback确保debounce函数稳定
    const debouncedSearch = useCallback(
        debounce(async (searchTerm) => {
            if (!searchTerm) {
                setResults([]);
                setIsOpen(false);
                return;
            }

            setIsLoading(true);
            try {
                const response = await searchCharacters(searchTerm);
                // 使用函数式更新确保获取最新状态
                setResults(prev => {
                    const newResults = Array.isArray(response) ? response : [];
                    console.log('Setting results:', newResults);
                    return newResults;
                });
                setIsOpen(true);
            } catch (error) {
                console.error("Error fetching characters:", error);
                setResults([]);
            } finally {
                setIsLoading(false);
            }
        }, 300),
        [] // 空依赖数组确保debounce函数只创建一次
    );

    // 点击外部关闭下拉框
    useEffect(() => {
        const handleClickOutside = (event) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // 处理搜索按钮点击
    const handleClick = () => {
        console.log("Button clicked:", inputTerm);
        debouncedSearch(inputTerm);
    };

    // 处理选择角色
    const handleSelect = async (item) => {
        try {
            const response = await getCharacterById(item.id);
            console.log('Selected character:', response);
            setResults([]);
            setIsOpen(false);
            setInputTerm(item.name); // 可选：将选中的名字填入输入框
        } catch (error) {
            console.error("Error fetching character details:", error);
        }
    };

    // 处理输入变化
    const handleInputChange = (e) => {
        const value = e.target.value;
        setInputTerm(value);
        // 如果输入为空，立即清除结果
        if (!value) {
            setResults([]);
            setIsOpen(false);
        }
    };

    return (
        <div className="App">
            <div>
                <h1>猜人物</h1>
            </div>
            <div className="search-dropdown" ref={dropdownRef}>
                <input
                    type="text"
                    value={inputTerm}
                    onChange={handleInputChange}
                    onKeyDown={(e) => e.key === 'Enter' && handleClick()}
                    placeholder="输入角色名..."
                    className={styles.standardInput}
                />
                <button
                    className={styles.buttonstyle}
                    onClick={handleClick}
                    disabled={isLoading || !inputTerm.trim()}
                >
                    {isLoading ? '搜索中...' : '搜索'}
                </button>
            </div>
            {isOpen && (
                <div className={styles.largeTextarea}>
                    {isLoading ? (
                        <div className={styles.standardInput}>加载中...</div>
                    ) : results.length > 0 ? (
                        results.map(item => (
                            <div
                                key={item.id}
                                onClick={() => handleSelect(item)}
                                className={styles.standardInput}
                                style={{ cursor: 'pointer' }}
                            >
                                {item.name}
                            </div>
                        ))
                    ) : (
                        <div className={styles.standardInput}>未找到结果</div>
                    )}
                </div>
            )}
        </div>
    );
}

export default GuessingCharacter;
